static class MapPatchesQuestTests {
    static void Check(bool b,string why){if(!b)throw new Exception(why);}
    static string Leaf(string p)=>p.Replace('\\','/').Split('/').Last();
    static int Flag(int source)=>MapNpcQuestState.Flag(source);
    static int Constant(byte[] b)=>b.Length==2?b[0]-64:BitConverter.ToInt32(b,1);
    static double Evaluate(byte[] code,IReadOnlyDictionary<int,bool> flags,bool action=true,bool ended=false,bool dead=false,double distance=1,int choice=0,bool open=true) {
        var stack=new List<double>();double Pop(){double n=stack[^1];stack.RemoveAt(stack.Count-1);return n;}
        for(int i=0;i<code.Length;i++){byte op=code[i];if(op<=0x7f)stack.Add(op-64);else if(op==0x82){stack.Add(BitConverter.ToInt32(code,i+1));i+=4;}
            else if(op is >=0x84 and <=0x8a){int count=op-0x84;var args=new double[count];for(int j=count-1;j>=0;j--)args[j]=Pop();int function=(int)Pop();stack.Add(function switch{1=>distance,3=>dead?1:0,15=>flags.GetValueOrDefault((int)args[0])?1:0,19=>0,21=>open?1:0,22=>choice,56=>action?1:0,57=>ended?1:0,_=>throw new Exception("Unexpected native function "+function)});}
            else if(op is 0x94 or 0x95 or 0x98 or 0x99){double b=Pop(),a=Pop();stack.Add(op switch{0x94=>a>b?1:0,0x95=>a==b?1:0,0x98=>a!=0&&b!=0?1:0,_=>a!=0||b!=0?1:0});}
            else if(op==0xa6)Check(stack.Count>0,"Invalid continuation");else if(op==0xa1){Check(i==code.Length-1&&stack.Count==1,"Invalid expression result");return Pop();}else throw new Exception("Unexpected ESD opcode "+op);
        }throw new Exception("Missing expression end");
    }
    static void Main(string[] args) {
        string sourceRoot=args[0],nativeRoot=args[1],definitions=args[2],output=args[3];Directory.CreateDirectory(output);var hashes=new Dictionary<string,string>();string Hash(byte[] b)=>Convert.ToHexStringLower(SHA256.HashData(b));
        byte[] Read(string root,string path){string full=Path.Combine(root,path);var bytes=File.ReadAllBytes(full);hashes.TryAdd(full,Hash(bytes));return bytes;}
        byte[]? Source(string path)=>File.Exists(Path.Combine(sourceRoot,path))?Read(sourceRoot,path):null;
        byte[] Native(string path)=>Read(nativeRoot,path);
        var sourceGame=BND3.Read(Source("param/GameParam/GameParam.parambnd.dcx")!);var sourceLots=PARAM.Read(sourceGame.Files.Single(f=>Leaf(f.Name)=="ItemLotParam.param").Bytes);sourceLots.ApplyParamdef(PARAMDEF.XmlDeserialize(Path.Combine(definitions,"ItemLotParam.xml")));var sourceLot=sourceLots.Rows.Single(r=>r.ID==1200);
        int Number(string field)=>Convert.ToInt32(sourceLot[field].Value);Check(Number("lotItemId01")==500&&Number("lotItemNum01")==1&&Number("lotItemCategory01")==MapItemPolicy.SourceGoodsCategory,"Source Patches gift changed");
        const int collection=52100688;var conversion=MapItemPolicy.Map(MapItemPolicy.SourceGoodsCategory,500,1,false)!;var reward=new MapItems.Lot(1200,90001200,Number("getItemFlagId"),collection,[conversion],0);
        var baseGame=Native("param/gameparam/gameparam.parambnd.dcx");var game=BND4.Read(baseGame);var lotFile=game.Files.Single(f=>Leaf(f.Name)=="ItemLotParam.param");var lotTable=ImportParam.Read(lotFile.Bytes,"ITEMLOT_PARAM_ST",148,2);ImportParam.Append(lotTable,lotTable.Rows.First(),reward.TargetID,"Imported DS1R lot 1200",MapItems.LotBytes([(1500,1,1000)],collection));lotFile.Bytes=ImportParam.Write(lotTable);var bakedGame=game.Write(game.Compression);
        byte[]? Composed(string path)=>path switch{"param/gameparam/gameparam.parambnd.dcx"=>bakedGame,"script/talk/m40_05_00_00.talkesdbnd.dcx"=>Native("script/talk/m24_00_00_00.talkesdbnd.dcx"),_=>File.Exists(Path.Combine(nativeRoot,path))?Native(path):null};
        var sourceMap=MSB1.Read(Source("map/MapStudio/m13_00_00_00.msb")!);var before=sourceMap.Write();var target=new MSBB();target.Models.Objects.Add(new("o696100"));target.Models.Objects.Add(new("o696101"));target.Parts.Objects.Add(new(){Name="fixture_lever",ModelName="o696100",EntityID=MapCatacombsBridges.Lever});target.Parts.Objects.Add(new(){Name="fixture_bridge",ModelName="o696101",EntityID=MapCatacombsBridges.Bridge});
        var nativeMap=MSBB.Read(Native("map/MapStudio/m21_00_00_00.msb.dcx"));var floorModel=(MSBB.Model.Collision)nativeMap.Models.Collisions[0].DeepCopy();floorModel.Name="h800000";target.Models.Collisions.Add(floorModel);var floor=(MSBB.Part.Collision)nativeMap.Parts.Collisions[0].DeepCopy();floor.Name="h800000_0000";floor.ModelName=floorModel.Name;target.Parts.Collisions.Add(floor);
        var triangles=new[]{new MapCollision.Triangle(new(-1000,-1000,-1000),new(1000,-1000,-1000),new(0,-1000,1000))};var chunks=new[]{new MapCollisionBindings.Chunk("h0900B0",triangles,triangles)};var script=new EMEVD(EMEVD.Game.Bloodborne);script.Events.Add(new(0));script.Events.Add(new(50));var sentinel=new EMEVD.Event(12416400);sentinel.Instructions.Add(new(1001,0,2f));script.Events.Add(sentinel);
        var offset=new Vector3(-143.8f,20.07f,164.63f);var result=MapPatchesQuest.Apply(Source,Native,Composed,sourceMap,target,offset,chunks,[floor],definitions,nativeRoot,"m40_05_00_00",script.Write(),reward);
        var reread=MSBB.Read(target.Write());var actor=reread.Parts.Enemies.Single();var from=sourceMap.Parts.Enemies.Single(p=>p.EntityID==6320);Check(actor.EntityID==4056320&&actor.NPCParamID==891100&&actor.ThinkParamID==-1&&actor.TalkID==405971&&actor.Position==from.Position+offset&&actor.CollisionName==floor.Name,"Source NPC/native interaction frame differs");
        Check(result.FaceGenID==6320&&result.Appearance.Any(p=>p.Slot=="Face")&&result.Appearance.Single(p=>p.Slot=="Body").RequestedID==301010&&result.Pose.Approximation&&result.Pose.Source==0,"Source appearance identity or explicit idle limitation changed");
        var model=FLVER2.Read(BND4.Read(result.Files["chr/c8911.chrbnd.dcx"]).Files.Single(f=>f.ID==200).Bytes);Check(model.Materials.Any(m=>m.Textures.Any(t=>t.Path.Contains("FG_import_6320_face",StringComparison.Ordinal))),"Patches has no actual FaceGen face");
        var sourceFaces=PARAM.Read(sourceGame.Files.Single(f=>Leaf(f.Name)=="FaceGenParam.param").Bytes);sourceFaces.ApplyParamdef(PARAMDEF.XmlDeserialize(Path.Combine(definitions,"FaceGenParam.xml")));var realFace=NpcFace.Load(Source,sourceFaces.Rows.Single(r=>r.ID==6320),1);
        Check(realFace.Model.Meshes.Count==3&&realFace.Model.Meshes.SelectMany(m=>m.Vertices).All(v=>float.IsFinite(v.Normal.LengthSquared())&&Math.Abs(v.Normal.LengthSquared()-1)<.00001f),"Patches small-eye morph generated missing/invalid normals");
        var bank=BND4.Read(result.Files["chr/c8911.anibnd.dcx"]);Check(result.Pose.NativeCarriers.Count==3&&result.Pose.NativeCarriers.All(id=>new NativeAnimation.Pack(bank.Files.Single(f=>f.ID==1000000000+id).Bytes.ToArray()).Int(new NativeAnimation.Pack(bank.Files.Single(f=>f.ID==1000000000+id).Bytes.ToArray()).Object("hkaSplineCompressedAnimation")+56)==result.Pose.Frames),"Source idle carriers differ");Check(TAE.Read(bank.Files.Single(f=>f.ID==3000000).Bytes).Animations.All(a=>a.Events.Count==0),"Donor Doll effects retained");
        var talk=BND4.Read(result.Files["script/talk/m40_05_00_00.talkesdbnd.dcx"]);var esd=ESD.Read(talk.Files.Single(f=>Leaf(f.Name)=="t405971.esd").Bytes);var states=esd.StateGroups[1];var flags=new Dictionary<int,bool>{{Flag(1620),true}};
        int? Choose(int state,bool ended=false,int choice=0,bool open=true,double distance=1,bool dead=false)=>states[state].Conditions.Where(c=>Evaluate(c.Evaluator,flags,ended:ended,choice:choice,open:open,distance:distance,dead:dead)!=0).Select(c=>(int?)c.TargetState).FirstOrDefault();
        void Enter(int state){foreach(var c in states[state].EntryCommands.Where(c=>c.CommandID==11))flags[Constant(c.Arguments[0])]=Constant(c.Arguments[1])!=0;}
        Check(Choose(100)==41&&Choose(41)==43&&Choose(43)==null&&Choose(43,ended:true)==19,"Fresh source greeting route failed");Enter(19);Check(flags[Flag(1637)]&&Choose(19)==null&&Choose(19,choice:1)==17&&Choose(19,open:false)==18,"Native first choice prematurely resolves/reversed");Enter(17);Check(flags[Flag(1638)]&&flags[Flag(71310066)]&&Choose(41)==20,"Cleric yes/resume route failed");Enter(68);Check(Choose(41)==44,"Completed yes does not repeat source greeting");
        flags=new(){{Flag(1620),true}};Enter(18);Enter(69);Check(Choose(41)==21,"Source No branch's authored71310076 resume predicate was changed");Check(Choose(43,distance:6)==3&&Choose(19,dead:true)==3,"Speech/popup interruption does not clean up");
        flags=new(){{Flag(1621),true}};Check(Choose(100)==42&&Choose(42)==45,"Late first meeting route failed");Enter(46);Check(flags[Flag(11300590)]&&Choose(42)==49,"Late introduction persistence failed");
        flags=new(){{Flag(1621),true},{Flag(1637),true}};Check(Choose(42)==47&&Choose(47,ended:true)==64&&Choose(64)==null,"Post-trap apology offer route failed");Enter(62);Check(Choose(42)==52&&!flags.GetValueOrDefault(Flag(11300591)),"Forgiveness gift happens before speech completion");Enter(65);Check(flags[Flag(11300591)]&&Choose(42)==50,"Forgiveness completion/repeat missing");
        flags=new(){{Flag(1621),true},{Flag(1637),true}};Enter(63);Check(Choose(42)==63&&Choose(63)==54,"Source nonmember refusal route failed");
        var events=EMEVD.Read(result.Script);var grant=events.Events.Single(e=>e.ID==MapPatchesQuest.FirstEvent+1);Check(grant.Instructions.Count==3&&grant.Instructions[0].ArgData[0]==0&&BitConverter.ToInt32(grant.Instructions[0].ArgData,4)==Flag(11300591)&&BitConverter.ToInt32(grant.Instructions[1].ArgData,4)==collection&&BitConverter.ToInt32(grant.Instructions[2].ArgData)==reward.TargetID,"One-time gift flag/award contract changed");
        var presence=events.Events.Single(e=>e.ID==MapPatchesQuest.FirstEvent);Check(presence.Instructions[3].Bank==2004&&presence.Instructions[3].ID==5&&presence.Instructions[3].ArgData[4]==1,"NPC is not enabled after fresh shared quest initialization");Check(presence.Instructions[7].Bank==1003&&presence.Instructions[7].ID==2&&BitConverter.ToInt32(presence.Instructions[7].ArgData,4)==Flag(1628),"Dead NPC corpse is hidden before reload");
        var originalTalk=BND4.Read(Composed("script/talk/m40_05_00_00.talkesdbnd.dcx")!);foreach(var f in originalTalk.Files)Check(talk.Files.Single(n=>n.ID==f.ID).Bytes.Span.SequenceEqual(f.Bytes.Span),"Original native talk member changed");
        foreach(var(path,bytes)in result.Files.Where(p=>p.Key.StartsWith("msg/",StringComparison.Ordinal))){var old=BND4.Read(Composed(path)!);var now=BND4.Read(bytes);foreach(var f in old.Files.Where(f=>f.ID is not(1 or 30)))Check(now.Files.Single(n=>n.ID==f.ID).Bytes.Span.SequenceEqual(f.Bytes.Span),"Unrelated localized FMG changed");foreach(int id in new[]{1,30}){var oldText=FMG.Read(old.Files.Single(f=>f.ID==id).Bytes);var newText=FMG.Read(now.Files.Single(f=>f.ID==id).Bytes);Check(oldText.Entries.All(e=>newText.Entries.Single(n=>n.ID==e.ID).Text==e.Text),"Original native subtitle/choice changed");}}
        Check(sourceMap.Write().SequenceEqual(before),"Source map mutated");foreach(var pair in hashes)Check(Hash(File.ReadAllBytes(pair.Key))==pair.Value,"Original source/native archive changed");
        foreach(var(path,bytes)in result.Files){string file=Path.Combine(output,"package",path);Directory.CreateDirectory(Path.GetDirectoryName(file)!);File.WriteAllBytes(file,bytes);}File.WriteAllBytes(Path.Combine(output,"map.msb.dcx"),target.Write(DCX.Type.DCX_DFLT_10000_44_9));File.WriteAllBytes(Path.Combine(output,"map.emevd.dcx"),result.Script);
        File.WriteAllText(Path.Combine(output,"validation.json"),JsonSerializer.Serialize(new{status="PASS",result.Appearance,result.FaceGenID,result.Pose,result.Dialogue,result.GiftLot,result.CollectionFlag,result.Limitations,sourceArchives=hashes,gameplayValidated=false},new JsonSerializerOptions{WriteIndented=true}));
        Console.WriteLine($"PASS Patches Catacombs fixture: real Face6320/Black Leather; native first/forgiveness choices, no input/interruption/recovery/late/repeats; source1200→Madman's Knowledge; {result.Dialogue.Speeches.Count} speech sequences / {result.Dialogue.Voices.Clips.Count} voices / {result.Dialogue.Languages} locales; {hashes.Count} original archives unchanged. Armed idle/hostile combat/later quest/native gameplay remain unproved.");
    }
